/* Original logging-preflight presentation. The optional command/script is never executed. */
(function(root){
  'use strict';
  const presets={
    fictional:{command:'+scene-date',reply:'IC 178-04-18',regex:'^IC (?<game_year>\\d{1,4})-(?<game_month>\\d{1,2})-(?<game_day>\\d{1,2})$'},
    bod:{command:'+loginfo',reply:'Game date: 18-4-178',regex:'^Game date: (?<game_day>\\d{1,2})-(?<game_month>\\d{1,2})-(?<game_year>\\d{1,4})$'}
  };
  function open(api){
    const {$,esc,state,profile,games,channelOf,ws,persist,sampleMessages,channels,showDialog}=api;
    const id=state.profile,p=profile(),game=games[p.game].name,stored=state.logging[id]||{};
    const defaults={folder:'Logs',pattern:'{game}/{character}/{date}-{channel}',format:'txt',start:'connection',include:'all',gather:false,mode:'command',preset:'fictional',command:presets.fictional.command,regex:presets.fictional.regex,reply:presets.fictional.reply};
    const opts={...defaults,...stored};
    let fields={},status=opts.gather?'waiting':'ready',worker=null,timeout=null,sequence=0;
    showDialog('Logging','GATHER FIELDS → CHOOSE NAME → START');
    $('tool-body').innerHTML=`<p class="tool-intro">Configure <strong>${esc(p.name)} / ${esc(game)}</strong>. Optional pre-start input gathers fields before choosing the filename. This study executes no commands or scripts and starts no logger.</p><div class="tool-form"><label>Base folder<input id="log-folder" value="${esc(opts.folder)}" maxlength="120"></label><label>Format<select id="log-format"><option value="txt" ${opts.format==='txt'?'selected':''}>Plain text (.txt)</option><option value="html" ${opts.format==='html'?'selected':''}>HTML (.html)</option></select></label><label class="full">File naming pattern<input id="log-pattern" value="${esc(opts.pattern)}" maxlength="240"><span class="subtle">Real date: {date}, {real_year}, {real_month}, {real_day} · Identity: {game}, {character}, {channel}<br>Gathered fields: {game_year}, {game_month}, {game_day}, or any named capture.</span></label><label>Start logging<select id="log-start"><option value="connection" ${opts.start==='connection'?'selected':''}>When this character connects</option><option value="manual" ${opts.start==='manual'?'selected':''}>Manually</option></select></label><label>Include<select id="log-include"><option value="all" ${opts.include==='all'?'selected':''}>All channels, with stream labels</option><option value="active" ${opts.include==='active'?'selected':''}>Active channel only</option></select></label></div><label class="gather-toggle"><input type="checkbox" id="log-gather" ${opts.gather?'checked':''}><span><strong>Gather fields before logging</strong><small>Preview a command or startup script, then match its reply.</small></span></label><section id="gather-fields" ${opts.gather?'':'hidden'}><div class="tool-form"><label>Example preset<select id="gather-preset"><option value="fictional" ${opts.preset==='fictional'?'selected':''}>Fictional game date</option><option value="bod" ${opts.preset==='bod'?'selected':''}>Blood of Dragons · +loginfo example</option></select></label><label>Pre-start input type<select id="gather-mode"><option value="command" ${opts.mode==='command'?'selected':''}>Game command</option><option value="script" ${opts.mode==='script'?'selected':''}>Startup script</option></select></label><label class="full">Command or script text · never executed<textarea id="gather-command" rows="2" maxlength="2000" spellcheck="false">${esc(opts.command)}</textarea></label><label class="full">Reply trigger / regular expression<input id="gather-regex" value="${esc(opts.regex)}" maxlength="500" spellcheck="false"><span class="subtle">Named groups become filename fields. This example uses JavaScript regex; native engine syntax must be verified.</span></label><label class="full">Sample reply · editable<textarea id="gather-reply" rows="2" maxlength="4000" spellcheck="false">${esc(opts.reply)}</textarea></label></div><div class="gather-actions"><button class="secondary" id="gather-run">Preview gather sequence</button><span class="subtle">No command, script, or network activity</span></div><p class="subtle" id="gather-preset-note">${opts.preset==='bod'?'The +loginfo command is a preset only. This sample response is illustrative; configure the regex from actual output before native use.':'All commands, dates and replies here are fictional examples.'}</p><div class="gather-state" role="status" aria-live="polite" id="gather-state"></div><div id="gather-values" class="gather-values"></div></section><div class="filename-preview"><div class="eyebrow">RESULTING PATH · PREVIEW</div><output id="log-filename"></output><small id="log-path-status"></small></div><div class="dialog-actions"><button class="secondary" id="log-download">Download fictional sample</button><button class="primary" id="log-save">Save preview preferences</button></div><p id="log-state" class="subtle" role="status"></p>`;
    const host=$('gather-fields');
    const read=()=>({folder:$('log-folder').value,pattern:$('log-pattern').value,format:$('log-format').value,start:$('log-start').value,include:$('log-include').value,gather:$('log-gather').checked,preset:$('gather-preset').value,mode:$('gather-mode').value,command:$('gather-command').value,regex:$('gather-regex').value,reply:$('gather-reply').value});
    function tokens(){const date=new Date(),year=String(date.getFullYear()),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return {...fields,game,character:p.name,channel:channelOf(ws().active),date:`${year}-${month}-${day}`,real_year:year,real_month:month,real_day:day};}
    function pathResult(){const o=read(),values=tokens(),missing=[];const replace=text=>text.replace(/\{([A-Za-z_][A-Za-z_0-9]*)\}/g,(all,key)=>{if(values[key]!==undefined&&values[key]!==null&&values[key]!=='')return String(values[key]);missing.push(key);return all;});const clean=text=>text.replace(/[<>:"\\|?*\x00-\x1f]/g,'_').replace(/\.\./g,'_');return {path:clean(replace(o.folder)).replace(/\/$/,'')+'/'+clean(replace(o.pattern))+'.'+o.format,missing:[...new Set(missing)]};}
    function update(){const o=read(),result=pathResult();host.hidden=!o.gather;$('log-filename').textContent=result.path;const ready=(!o.gather||status==='matched')&&!result.missing.length;$('log-download').disabled=!ready;$('log-path-status').textContent=result.missing.length?'Missing fields: '+result.missing.join(', ')+'. A filename has not been finalized.':o.gather&&status!=='matched'?'Waiting for the pre-start match before finalizing the filename.':'Filename preview ready. No logger starts and no folder is accessed.';if(o.gather){$('gather-state').textContent=status==='waiting'?'○ Waiting — preview the pre-start sequence to gather fields.':status==='running'?'◷ Waiting for a sample reply match…':status==='matched'?'✓ Matched — fields gathered before choosing the filename.':status==='missing'?'! Missing fields — the sample reply did not match, or supplied no named fields.':status.startsWith('error:')?'! '+status.slice(6):status;$('gather-values').replaceChildren();for(const [key,value] of Object.entries(fields)){const line=document.createElement('code');line.textContent=`${key} = ${value}`;$('gather-values').append(line);}}}
    function stop(){sequence++;clearTimeout(timeout);if(worker){worker.terminate();worker=null;}}
    function invalidate(){stop();fields={};status=$('log-gather').checked?'waiting':'ready';update();}
    ['log-folder','log-pattern','log-format','log-start','log-include'].forEach(name=>$(name).oninput=update);
    ['gather-command','gather-regex','gather-reply','gather-mode'].forEach(name=>$(name).oninput=invalidate);
    $('log-gather').onchange=()=>{if($('log-gather').checked&&$('log-pattern').value===defaults.pattern)$('log-pattern').value='{game}/{character}/{game_year}-{game_month}-{game_day} - {date}-{channel}';invalidate();};
    $('gather-preset').onchange=()=>{const preset=presets[$('gather-preset').value];$('gather-command').value=preset.command;$('gather-reply').value=preset.reply;$('gather-regex').value=preset.regex;$('gather-mode').value='command';$('gather-preset-note').textContent=$('gather-preset').value==='bod'?'The +loginfo command is a preset only. This response is illustrative; configure the regex from actual output before native use.':'All commands, dates and replies here are fictional examples.';invalidate();};
    function receive(result,run){if(run!==sequence||!host.isConnected)return;clearTimeout(timeout);worker?.terminate();worker=null;fields=result.fields||{};status=result.error?'error:'+result.error:result.matched&&Object.keys(fields).length?'matched':'missing';update();}
    $('gather-run').onclick=()=>{stop();fields={};status='running';update();const run=sequence,o=read();if(!o.command.trim()){status='error:Enter a pre-start command or script to preview. Nothing will execute.';update();return;}
      if(location.protocol==='file:'){
        // A direct-file browser often disallows workers. Only the fixed preset can be parsed synchronously.
        const preset=presets[o.preset];if(o.regex===preset.regex){timeout=setTimeout(()=>{const match=(o.preset==='bod'?/^Game date: (?<game_day>\d{1,2})-(?<game_month>\d{1,2})-(?<game_year>\d{1,4})$/:/^IC (?<game_year>\d{1,4})-(?<game_month>\d{1,2})-(?<game_day>\d{1,2})$/).exec(o.reply);receive({matched:!!match,fields:match?.groups||{}},run);},250);}else {status='error:Custom regex preview needs a local HTTP server so it can run in a bounded worker. Fixed presets work from a file URL.';update();}return;
      }
      try{worker=new Worker('log-field-worker.js');worker.onmessage=e=>receive(e.data,run);worker.onerror=e=>{e.preventDefault();receive({error:'Reply parser could not start. Serve the complete prototype locally, including log-field-worker.js.'},run);};timeout=setTimeout(()=>{if(run!==sequence)return;worker?.terminate();worker=null;status='error:Regex preview timed out after 1 second. Simplify the expression or sample.';if(host.isConnected)update();},1000);worker.postMessage({pattern:o.regex,reply:o.reply});}catch{receive({error:'This browser cannot start the sample parser worker.'},run);}
    };
    $('log-save').onclick=()=>{state.logging[id]=read();persist();$('log-state').textContent='Preview preferences saved. No pre-start input ran and no logger was started.';};
    $('log-download').onclick=()=>{const o=read(),result=pathResult();if(result.missing.length||o.gather&&status!=='matched')return;const names=o.include==='all'?channels.filter(c=>!['Notes','Activity'].includes(c)):[channelOf(ws().active)];const text=`VALYRIA — FICTIONAL SAMPLE LOG\n${p.name} / ${game}\nNo live connection.\n${Object.entries(fields).map(([k,v])=>k+'='+v).join(' · ')}\n\n`+names.map(c=>`[${c}]\n`+(c==='Main'?`${p.room}\nEvening settles over the courtyard.`:sampleMessages(c,id).map(([name,content,time])=>`${time} ${name}: ${content}`).join('\n'))).join('\n\n');const body=o.format==='html'?`<!doctype html><html lang="en"><meta charset="utf-8"><title>Fictional Valyria sample log</title><body><pre>${esc(text)}</pre></body></html>`:text;const url=URL.createObjectURL(new Blob([body],{type:o.format==='html'?'text/html':'text/plain'}));const link=document.createElement('a');link.href=url;link.download=result.path.split('/').pop();link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('log-state').textContent='Fictional sample offered as a browser download. The configured folder was not accessed.';};
    $('tool-dialog').addEventListener('close',stop,{once:true});update();
  }
  root.ValyriaLogging={open};
})(window);
